import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';

const EmployeeManagementPage = () => {
  const navigate = useNavigate();
  const [employees, setEmployees] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  // --- NEW: State to track selected employee IDs ---
  const [selectedEmployees, setSelectedEmployees] = useState([]);

  // --- (fetchEmployees and handleDelete functions are the same as before) ---

  // --- NEW: Handlers for checkbox selection ---
  const handleSelectAll = (e) => {
    if (e.target.checked) {
      // Select all employee IDs
      setSelectedEmployees(employees.map(emp => emp.id));
    } else {
      // Deselect all
      setSelectedEmployees([]);
    }
  };

  const handleSelectOne = (e, id) => {
    if (e.target.checked) {
      // Add ID to the selection
      setSelectedEmployees([...selectedEmployees, id]);
    } else {
      // Remove ID from the selection
      setSelectedEmployees(selectedEmployees.filter(empId => empId !== id));
    }
  };

  // --- NEW: Handler for the "Run Payroll" action ---
  const handleRunPayroll = () => {
    if (selectedEmployees.length === 0) {
      alert("Please select at least one employee to run payroll.");
      return;
    }
    // In a real app, you would pass these IDs to the Run Payroll page
    // For now, we'll just log them and navigate
    console.log("Running payroll for employee IDs:", selectedEmployees);
    navigate('/run-payroll');
  };

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-3xl font-bold">Staff & Faculty Directory</h1>
          <p className="text-sm text-subtext-light">{selectedEmployees.length} employee(s) selected</p>
        </div>
        {/* --- NEW: Actions dropdown button --- */}
        <div className="flex items-center space-x-2">
          <button 
            onClick={handleRunPayroll}
            disabled={selectedEmployees.length === 0}
            className="bg-primary text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center hover:bg-blue-600 disabled:bg-gray-400"
          >
            <span className="material-icons mr-2 text-base">play_arrow</span> Run Payroll for Selected
          </button>
          <Link to="/add-employee" className="bg-gray-200 text-gray-700 px-4 py-2 rounded-lg text-sm font-medium">Add New Staff</Link>
        </div>
      </div>

      <div className="bg-card-light dark:bg-card-dark p-6 rounded-xl shadow-sm overflow-x-auto">
        <table className="w-full text-sm text-left">
          <thead className="text-xs uppercase bg-background-light">
            <tr>
              <th className="p-4">
                <input 
                  type="checkbox" 
                  className="form-checkbox"
                  onChange={handleSelectAll}
                  // Check if all employees are selected
                  checked={employees.length > 0 && selectedEmployees.length === employees.length}
                />
              </th>
              <th className="px-6 py-3">Name</th>
              <th className="px-6 py-3">Staff ID</th>
              <th className="px-6 py-3">Department</th>
              {/* ... other headers */}
            </tr>
          </thead>
          <tbody>
            {employees.map((employee) => (
              <tr key={employee.id} className="border-b hover:bg-gray-50">
                <td className="w-4 p-4">
                  <input 
                    type="checkbox" 
                    className="form-checkbox" 
                    onChange={(e) => handleSelectOne(e, employee.id)}
                    // Check if this specific employee is in the selected list
                    checked={selectedEmployees.includes(employee.id)}
                  />
                </td>
                <td className="px-6 py-4 font-medium">
                  <Link to={`/employees/${employee.id}`} className="hover:text-primary">{employee.firstName} {employee.lastName}</Link>
                </td>
                <td className="px-6 py-4">{employee.employeeId}</td>
                <td className="px-6 py-4">{employee.department}</td>
                {/* ... other cells */}
              </tr>
            ))}
          </tbody>
        </table>
        {/* ... Pagination Controls ... */}
      </div>
    </div>
  );
};

export default EmployeeManagementPage;
